if cp.exists():r['validation']=[{'kind':'bounded_independent_controls','path':str(cp.relative_to(H.parents[1])).replace('\\','/'),'sha256':hashlib.sha256(cp.read_bytes()).hexdigest(),'summary':'Seven planned controls: six observed; shell subshell control unavailable due to MSYS launch failure. No retained scripts, providers, native owners or private benchmark accessed.'}]
